	    Operator entity = new Operator();
            entity.setOperatorId( event.getOperatorId() );
            entity.setName( event.getName() );
            entity.setIcaoDesignator( event.getIcaoDesignator() );
            entity.setOperatorType( event.getOperatorType() );
	    
    	// ------------------------------------------
