    @SuppressWarnings("unused")
    @QueryHandler
    public List<Operator> handle( FindAllOperatorQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindOperator,
 * but only if the id matches
 *
 * @param		entity	Operator
 */
	protected void emitFindOperator( Operator entity ) {
		LOGGER.info("handling emitFindOperator" );
		
	    queryUpdateEmitter.emit(FindOperatorQuery.class,
	                            query -> query.getFilter().getOperatorId().equals(entity.getOperatorId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllOperator
	 * 
	 * @param		entity	Operator
	 */
	protected void emitFindAllOperator( Operator entity ) {
		LOGGER.info("handling emitFindAllOperator" );
		
	    queryUpdateEmitter.emit(FindAllOperatorQuery.class,
	                            query -> true,
	                            entity);
	}

